Artwork::Artwork(std::unique_ptr<const Concept> pimpl) noexcept
    : service::Object{getTypeNames(), getResolvers()},
      _pimpl{std::move(pimpl)} {
}

service::TypeNames Artwork::getTypeNames() const noexcept {
  return {R"gql(Artwork)gql"sv};
}

service::ResolverMap Artwork::getResolvers() const noexcept {
  return {{R"gql(id)gql"sv,
           [this](service::ResolverParams &&params) {
             return resolveId(std::move(params));
           }},
          {R"gql(tags)gql"sv,
           [this](service::ResolverParams &&params) {
             return resolveTags(std::move(params));
           }},
          {R"gql(title)gql"sv,
           [this](service::ResolverParams &&params) {
             return resolveTitle(std::move(params));
           }},
          {R"gql(tagIds)gql"sv,
           [this](service::ResolverParams &&params) {
             return resolveTagIds(std::move(params));
           }},
          {R"gql(artists)gql"sv,
           [this](service::ResolverParams &&params) {
             return resolveArtists(std::move(params));
           }},
          {R"gql(imageIds)gql"sv,
           [this](service::ResolverParams &&params) {
             return resolveImageIds(std::move(params));
           }},
          {R"gql(tagPaths)gql"sv,
           [this](service::ResolverParams &&params) {
             return resolveTagPaths(std::move(params));
           }},
          {R"gql(artistIds)gql"sv,
           [this](service::ResolverParams &&params) {
             return resolveArtistIds(std::move(params));
           }},
          {R"gql(createdAt)gql"sv,
           [this](service::ResolverParams &&params) {
             return resolveCreatedAt(std::move(params));
           }},
          {R"gql(updatedAt)gql"sv,
           [this](service::ResolverParams &&params) {
             return resolveUpdatedAt(std::move(params));
           }},
          {R"gql(__typename)gql"sv,
           [this](service::ResolverParams &&params) {
             return resolve_typename(std::move(params));
           }},
          {R"gql(imageCount)gql"sv,
           [this](service::ResolverParams &&params) {
             return resolveImageCount(std::move(params));
           }},
          {R"gql(description)gql"sv,
           [this](service::ResolverParams &&params) {
             return resolveDescription(std::move(params));
           }},
          {R"gql(publishedAt)gql"sv, [this](service::ResolverParams &&params) {
             return resolvePublishedAt(std::move(params));
           }}};
}

void Artwork::beginSelectionSet(
    const service::SelectionSetParams &params) const {
  _pimpl->beginSelectionSet(params);
}

void Artwork::endSelectionSet(const service::SelectionSetParams &params) const {
  _pimpl->endSelectionSet(params);
}

service::AwaitableResolver
Artwork::resolveId(service::ResolverParams &&params) const {
  std::unique_lock resolverLock(_resolverMutex);
  service::SelectionSetParams selectionSetParams{
      static_cast<const service::SelectionSetParams &>(params)};
  auto directives = std::move(params.fieldDirectives);
  auto result = _pimpl->getId(service::FieldParams{
      std::move(selectionSetParams), std::move(directives)});
  resolverLock.unlock();

  return service::ModifiedResult<response::IdType>::convert(std::move(result),
                                                            std::move(params));
}

