void AddArtworkDetails(const std::shared_ptr<schema::ObjectType> &typeArtwork,
                       const std::shared_ptr<schema::Schema> &schema) {
  typeArtwork->AddFields(
      {schema::Field::Make(
           R"gql(id)gql"sv, R"md(作品 ID。)md"sv, std::nullopt,
           schema->WrapType(introspection::TypeKind::NON_NULL,
                            schema->LookupType(R"gql(ID)gql"sv))),
       schema::Field::Make(
           R"gql(title)gql"sv, R"md(作品标题。)md"sv, std::nullopt,
           schema->WrapType(introspection::TypeKind::NON_NULL,
                            schema->LookupType(R"gql(String)gql"sv))),
       schema::Field::Make(R"gql(description)gql"sv,
                           R"md(作品描述，未填写时为 null。)md"sv, std::nullopt,
                           schema->LookupType(R"gql(String)gql"sv)),
       schema::Field::Make(
           R"gql(publishedAt)gql"sv, R"md(原始发布时间，未知时为 null。)md"sv,
           std::nullopt, schema->LookupType(R"gql(String)gql"sv)),
       schema::Field::Make(
           R"gql(createdAt)gql"sv, R"md(创建时间。)md"sv, std::nullopt,
           schema->WrapType(introspection::TypeKind::NON_NULL,
                            schema->LookupType(R"gql(String)gql"sv))),
       schema::Field::Make(
           R"gql(updatedAt)gql"sv, R"md(最后更新时间。)md"sv, std::nullopt,
           schema->WrapType(introspection::TypeKind::NON_NULL,
                            schema->LookupType(R"gql(String)gql"sv))),
       schema::Field::Make(
           R"gql(imageCount)gql"sv, R"md(图片数量。)md"sv, std::nullopt,
           schema->WrapType(introspection::TypeKind::NON_NULL,
                            schema->LookupType(R"gql(Int)gql"sv))),
       schema::Field::Make(
           R"gql(imageIds)gql"sv,
           R"md(图片 ID 列表，按作品内 position 升序。)md"sv, std::nullopt,
           schema->WrapType(
               introspection::TypeKind::NON_NULL,
               schema->WrapType(
                   introspection::TypeKind::LIST,
                   schema->WrapType(introspection::TypeKind::NON_NULL,
                                    schema->LookupType(R"gql(ID)gql"sv))))),
       schema::Field::Make(
           R"gql(tagIds)gql"sv, R"md(标签 ID 列表。)md"sv, std::nullopt,
           schema->WrapType(
               introspection::TypeKind::NON_NULL,
               schema->WrapType(
                   introspection::TypeKind::LIST,
                   schema->WrapType(introspection::TypeKind::NON_NULL,
                                    schema->LookupType(R"gql(ID)gql"sv))))),
       schema::Field::Make(
           R"gql(tags)gql"sv, R"md(标签列表，name 是该标签自身的标准名。)md"sv,
           std::nullopt,
           schema->WrapType(
               introspection::TypeKind::NON_NULL,
               schema->WrapType(
                   introspection::TypeKind::LIST,
                   schema->WrapType(introspection::TypeKind::NON_NULL,
                                    schema->LookupType(R"gql(Tag)gql"sv))))),
       schema::Field::Make(
           R"gql(tagPaths)gql"sv,
           R"md(标签路径列表，path 是从根标签到该标签自身、用 :: 连接的路径。)md"sv,
           std::nullopt,
           schema->WrapType(
               introspection::TypeKind::NON_NULL,
               schema->WrapType(
                   introspection::TypeKind::LIST,
                   schema->WrapType(
                       introspection::TypeKind::NON_NULL,
                       schema->LookupType(R"gql(TagPath)gql"sv))))),
       schema::Field::Make(
           R"gql(artistIds)gql"sv, R"md(艺术家 ID 列表。)md"sv, std::nullopt,
           schema->WrapType(
               introspection::TypeKind::NON_NULL,
               schema->WrapType(
                   introspection::TypeKind::LIST,
                   schema->WrapType(introspection::TypeKind::NON_NULL,
                                    schema->LookupType(R"gql(ID)gql"sv))))),
       schema::Field::Make(
           R"gql(artists)gql"sv, R"md(艺术家列表。)md"sv, std::nullopt,
           schema->WrapType(
               introspection::TypeKind::NON_NULL,
               schema->WrapType(
                   introspection::TypeKind::LIST,
                   schema->WrapType(
                       introspection::TypeKind::NON_NULL,
                       schema->LookupType(R"gql(Artist)gql"sv)))))});
}

